def f(inputs: List[Tuple[int, int, List[str], int, List[str]]]):
    '''
    inputs: a list of tuples, each containing:
        - an integer H
        - an integer W
        - a list of H strings, each of length W
        - an integer n
        - a list of n characters
    '''
    res = []
    for (h, w, grid, n, ops) in inputs:
        def calc(x):
            if len(x) == 1:
                return int(x[0])
            else:
                a, op, b = x
                if op == '+':
                    return calc(a) + calc(b)
                elif op == '-':
                    return calc(a) - calc(b)
                elif op == '*':
                    return calc(a) * calc(b)
                elif op == '/':
                    return calc(a) / calc(b)
        grid = list(map(list, zip(*grid)))
        grid = [list(i) for i in grid]
        def astar(x, y):
            if x < 0 or y < 0 or x >= h or y >= w or grid[x][y] == '#':
                return None
            c = int(grid[x][y])
            if c == 0:
                ops = ops[:-1]
            else:
                ops = ops[1:]
            op = ops[0]
            grid[x][y] = str(calc(c))
            if len(ops) == 1 and op == '=':
                if int(calc(c)) == x + y + calc(ops[0]):
                    return (x, y)
                else:
                    return None
            for dx, dy in ((0,1), (1,0), (1,1), (0, -1), (-1, 0), (1,0)):
                r = astar(x + dx, y + dy)
                if r is not None:
                    return r
            return None
        astar(0, 0)
        res.append(''.join(''.join(i) for i in grid))
    return res
``` 

